// Accepts either a proxy-forwarded event (X-Proxy-Secret) or a direct Retell POST.
// Direct posts are checked with the Retell HMAC when the raw body is still a string.
// The Node proxy (server/retell-proxy.mjs) verifies the raw body, then forwards here.
const item = $input.first().json;
const headers = item.headers || {};
let apiKey = '';
let shared = '';
let laravel = '';
try {
  apiKey = $env.RETELL_API_KEY || '';
  shared = $env.PROXY_SHARED_SECRET || $env.N8N_WEBHOOK_SECRET || '';
  laravel = ($env.LARAVEL_API_URL || '').replace(/\/$/, '');
} catch (err) {
  throw new Error('Allow n8n environment access for RETELL_API_KEY.');
}
const presented = headers['x-proxy-secret'] || headers['x-n8n-secret'] || '';
const proxyTrusted = Boolean(shared) && presented === shared;
let raw = null;
let parsed = null;
if (typeof item.body === 'string') {
  raw = item.body;
  parsed = JSON.parse(item.body);
} else if (item.body && typeof item.body === 'object') {
  parsed = item.body;
} else if (item.event) {
  parsed = item;
} else {
  throw new Error('Webhook body was empty.');
}
const signature = headers['x-retell-signature'] || '';
if (!proxyTrusted) {
  if (!signature || !raw) {
    throw new Error('Signature could not be checked on a parsed body. Point Retell at the proxy POST /v1/retell-webhook (it verifies the raw body, then forwards with X-Proxy-Secret).');
  }
  if (!apiKey) throw new Error('Set RETELL_API_KEY. Retell signs webhooks with that key (the bdhousing-voice key that has the webhook badge).');
  let crypto;
  try { crypto = require('crypto'); } catch (err) {
    throw new Error('Enable Node crypto in n8n (NODE_FUNCTION_ALLOW_BUILTIN=crypto) or verify webhooks on the proxy.');
  }
  const match = /^v=(\d+),d=(.*)$/.exec(signature);
  if (!match) throw new Error('X-Retell-Signature is missing the v=,d= form.');
  if (Math.abs(Date.now() - Number(match[1])) > 5 * 60 * 1000) throw new Error('Retell signature timestamp is outside the 5 minute window.');
  const expected = crypto.createHmac('sha256', apiKey).update(raw + match[1]).digest('hex');
  const ok = expected.length === match[2].length && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(match[2]));
  if (!ok) throw new Error('Invalid Retell webhook signature.');
}
const event = String(parsed.event || '').replace(/\./g, '_');
const allowed = ['call_started', 'call_ended', 'call_analyzed', 'transcript_updated'];
if (!allowed.includes(event)) {
  return [{ json: { event, ignored: true, call_id: null, forward_to_laravel: 'no', laravel_url: '' } }];
}
const call = parsed.call || {};
return [{ json: {
  event,
  call_id: call.call_id || null,
  call_type: call.call_type || null,
  direction: call.direction || null,
  agent_id: call.agent_id || null,
  from_number: call.from_number || null,
  to_number: call.to_number || null,
  call_status: call.call_status || null,
  disconnection_reason: call.disconnection_reason || null,
  transcript: call.transcript || null,
  recording_url: call.recording_url || null,
  call_analysis: call.call_analysis || null,
  metadata: call.metadata || null,
  forward_to_laravel: laravel ? 'yes' : 'no',
  laravel_url: laravel ? laravel + '/api/retell/webhook' : ''
} }];
